def sum_diagonal_lengths(n):
    total_length = 0

    # 1. Main Diagonals (i - j = k)
    # k ranges from -(n-1) to n-1
    for k in range(-(n - 1), n):
        length = n - abs(k)
        if length % 3 == 0:
            total_length += length

    # 2. Anti-Diagonals (i + j = s)
    # s ranges from 2 to 2n
    for s in range(2, 2 * n + 1):
        # Length L_s = n - |s - (n+1)|
        length = n - abs(s - (n + 1))
        if length % 3 == 0:
            total_length += length

    return total_length

# Test for small values of n
tests = [3, 4, 6, 7, 12]
results = {}
for n in tests:
    results[n] = sum_diagonal_lengths(n)

print(results)

